1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useRef, useState } from "react";
6	import { NxLogo } from "./Logo";
7	import { ClaudeMark } from "./ClaudeMark";
8	import {
9	  IconServer,
10	  IconGame,
11	  IconSpark,
12	  IconDisk,
13	  IconNetwork,
14	  IconGlobe,
15	  IconMail,
16	  IconCode,
17	  IconApps,
18	  IconArrow,
19	} from "./icons";
20	
21	/**
22	 * Marketing top nav (v2 redesign). A grouped structure instead of a flat link
23	 * list: a Products mega-menu organized by outcome (Compute / Storage & Network /
24	 * Web Essentials) plus a "by use case" rail, then Pricing · Compare · Blog and a
25	 * Company dropdown. One prominent primary CTA; a live Status pill on the right.
26	 */
27	
28	type Item = { label: string; href: string; desc: string; icon: (p: { size?: number }) => React.ReactNode; badge?: string };
29	
30	const PRODUCT_GROUPS: { title: string; items: Item[] }[] = [
31	  {
32	    title: "Compute",
33	    items: [
34	      { label: "VPS Hosting", href: "/vps", desc: "Full-root NVMe KVM servers", icon: IconServer },
35	      { label: "Game Servers", href: "/game-servers", desc: "Minecraft, Rust, Valheim & more", icon: IconGame },
36	      { label: "Claude AI Builder", href: "/features", desc: "Build your server in plain English", icon: ClaudeMark, badge: "New" },
37	      { label: "Matrix", href: "/matrix", desc: "Build several apps at once with AI", icon: IconApps, badge: "New" },
38	    ],
39	  },
40	  {
41	    title: "Storage & Network",
42	    items: [
43	      { label: "Block Storage", href: "/block-storage", desc: "Add-on NVMe volumes", icon: IconDisk },
44	      { label: "Dedicated IPv4", href: "/vps", desc: "A clean, static IP per server", icon: IconNetwork },
45	    ],
46	  },
47	  {
48	    title: "Web Essentials",
49	    items: [
50	      { label: "Web Hosting", href: "/web-hosting", desc: "One-click WordPress & sites", icon: IconApps, badge: "New" },
51	      { label: "Domains", href: "/domains", desc: "Register & manage domains", icon: IconGlobe },
52	      { label: "Business Email", href: "/business-email", desc: "Mailboxes on your own domain", icon: IconMail },
53	    ],
54	  },
55	];
56	
57	const USE_CASES: Item[] = [
58	  { label: "Vibe coding", href: "/vibe-coding", desc: "Build sites & apps, no code", icon: IconSpark, badge: "New" },
59	  { label: "Free tools", href: "/tools", desc: "WHOIS, DNS, SSL & more", icon: IconNetwork, badge: "Free" },
60	  { label: "Migrate to Nxeon", href: "/migrate", desc: "Free — bring your servers", icon: IconArrow },
61	  { label: "Developers & API", href: "/developers", desc: "Automate everything", icon: IconCode },
62	  { label: "AI apps & agents", href: "/features", desc: "Ship agents in minutes", icon: IconSpark },
63	];
64	
65	const COMPANY: { label: string; href: string }[] = [
66	  { label: "About", href: "/about" },
67	  { label: "Security", href: "/security" },
68	  { label: "Contact", href: "/contact" },
69	  { label: "Affiliate program", href: "/affiliate" },
70	  { label: "Status", href: "/status" },
71	];
72	
73	export function MarketingHeader() {
74	  const pathname = usePathname();
75	  const [open, setOpen] = useState(false); // mobile drawer
76	  const [menu, setMenu] = useState<null | "products" | "company">(null); // desktop dropdown
77	  const [scrolled, setScrolled] = useState(false);
78	  const [authed, setAuthed] = useState(false);
79	  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
80	
81	  // Show "Back to portal" for a signed-in visitor while keeping marketing pages
82	  // static. Two-step, after mount: (1) optimistic read of the non-httpOnly
83	  // `nxeon_authed` flag cookie (instant, no flash when present), then (2) an
84	  // authoritative probe to /api/auth/status which reads the real session cookie
85	  // server-side — so it's correct even if the flag cookie is missing or stale.
86	  useEffect(() => {
87	    setAuthed(document.cookie.split("; ").some((c) => c.startsWith("nxeon_authed=")));
88	    let alive = true;
89	    fetch("/api/auth/status", { cache: "no-store" })
90	      .then((r) => (r.ok ? r.json() : null))
91	      .then((d) => {
92	        if (alive && d && typeof d.authed === "boolean") setAuthed(d.authed);
93	      })
94	      .catch(() => {});
95	    return () => {
96	      alive = false;
97	    };
98	  }, []);
99	
100	  useEffect(() => {
101	    const onScroll = () => setScrolled(window.scrollY > 8);
102	    onScroll();
103	    window.addEventListener("scroll", onScroll, { passive: true });
104	    return () => window.removeEventListener("scroll", onScroll);
105	  }, []);
106	
107	  useEffect(() => {
108	    setOpen(false);
109	    setMenu(null);
110	  }, [pathname]);
111	
112	  // Hover-intent: brief close delay so diagonal mouse travel to the panel doesn't drop it.
113	  const openMenu = (m: "products" | "company") => {
114	    if (closeTimer.current) clearTimeout(closeTimer.current);
115	    setMenu(m);
116	  };
117	  const scheduleClose = () => {
118	    if (closeTimer.current) clearTimeout(closeTimer.current);
119	    closeTimer.current = setTimeout(() => setMenu(null), 120);
120	  };
121	
122	  return (
123	    <header
124	      className={`sticky top-0 z-50 border-b transition-colors duration-300 ${
125	        scrolled || menu ? "border-white/[0.06] bg-navy-950/85 backdrop-blur-xl" : "border-transparent bg-transparent"
126	      }`}
127	      onMouseLeave={scheduleClose}
128	    >
129	      <div className="rail flex h-[72px] items-center justify-between">
130	        <Link href="/" aria-label="Nxeon home" className="shrink-0">
131	          <NxLogo id="hdr" size={44} />
132	        </Link>
133	
134	        {/* Desktop nav */}
135	        <nav className="hidden items-center gap-1 lg:flex">
136	          <button
137	            className={`nav-trigger nav-underline ${menu === "products" ? "is-open" : ""}`}
138	            onMouseEnter={() => openMenu("products")}
139	            onFocus={() => openMenu("products")}
140	            aria-expanded={menu === "products"}
141	          >
142	            Products <Chevron open={menu === "products"} />
143	          </button>
144	          <TopLink href="/matrix" pathname={pathname}>Matrix</TopLink>
145	          <TopLink href="/pricing" pathname={pathname}>Pricing</TopLink>
146	          <TopLink href="/compare" pathname={pathname}>Compare</TopLink>
147	          <TopLink href="/blog" pathname={pathname}>Blog</TopLink>
148	          <button
149	            className={`nav-trigger nav-underline ${menu === "company" ? "is-open" : ""}`}
150	            onMouseEnter={() => openMenu("company")}
151	            onFocus={() => openMenu("company")}
152	            aria-expanded={menu === "company"}
153	          >
154	            Company <Chevron open={menu === "company"} />
155	          </button>
156	        </nav>
157	
158	        <div className="hidden items-center gap-2 lg:flex">
159	          <Link href="/status" className="flex items-center gap-1.5 rounded-full border border-white/[0.07] px-2.5 py-1 text-xs text-slate-400 transition-colors hover:text-white">
160	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
161	            Status
162	          </Link>
163	          {authed ? (
164	            <>
165	              <Link href="/dashboard/settings" className="btn-ghost">My account</Link>
166	              <Link href="/dashboard" className="btn-primary">Back to portal</Link>
167	            </>
168	          ) : (
169	            <>
170	              <Link href="/login" className="btn-ghost">Log in</Link>
171	              <Link href="/register" className="btn-primary">Get started</Link>
172	            </>
173	          )}
174	        </div>
175	
176	        <button
177	          className="btn-ghost rounded-lg p-2 lg:hidden"
178	          aria-label="Toggle menu"
179	          aria-expanded={open}
180	          onClick={() => setOpen((v) => !v)}
181	        >
182	          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
183	            {open ? <path d="M6 6l12 12M18 6 6 18" /> : <path d="M4 7h16M4 12h16M4 17h16" />}
184	          </svg>
185	        </button>
186	      </div>
187	
188	      {/* Desktop mega-menu panels */}
189	      {menu === "products" && (
190	        <div
191	          className="absolute inset-x-0 top-full hidden lg:block"
192	          onMouseEnter={() => openMenu("products")}
193	          onMouseLeave={scheduleClose}
194	        >
195	          <div className="rail pb-6">
196	            <div className="grid grid-cols-[1.1fr_1.1fr_1.1fr_0.9fr] gap-2 rounded-2xl border border-white/10 bg-navy-950/95 p-3 shadow-2xl backdrop-blur-2xl">
197	              {PRODUCT_GROUPS.map((g) => (
198	                <div key={g.title} className="p-2">
199	                  <p className="section-label mb-2 px-2">{g.title}</p>
200	                  <div className="space-y-0.5">
201	                    {g.items.map((it) => (
202	                      <MegaItem key={it.label} item={it} />
203	                    ))}
204	                  </div>
205	                </div>
206	              ))}
207	              <div className="rounded-xl bg-white/[0.02] p-2">
208	                <p className="section-label mb-2 px-2">By use case</p>
209	                <div className="space-y-0.5">
210	                  {USE_CASES.map((it) => (
211	                    <MegaItem key={it.label} item={it} />
212	                  ))}
213	                </div>
214	                <div className="mx-2 my-2 border-t border-white/[0.06]" />
215	                <Link href="/features" className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-brand-300 hover:bg-white/[0.04]">
216	                  All features <IconArrow size={15} />
217	                </Link>
218	              </div>
219	            </div>
220	          </div>
221	        </div>
222	      )}
223	
224	      {menu === "company" && (
225	        <div
226	          className="absolute inset-x-0 top-full hidden lg:block"
227	          onMouseEnter={() => openMenu("company")}
228	          onMouseLeave={scheduleClose}
229	        >
230	          <div className="rail flex justify-end pb-6">
231	            <div className="w-56 rounded-2xl border border-white/10 bg-navy-950/95 p-2 shadow-2xl backdrop-blur-2xl">
232	              {COMPANY.map((l) => (
233	                <Link key={l.href} href={l.href} className="flex items-center justify-between rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white">
234	                  {l.label}
235	                  {l.label === "Status" && <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />}
236	                </Link>
237	              ))}
238	            </div>
239	          </div>
240	        </div>
241	      )}
242	
243	      {/* Mobile drawer */}
244	      {open && (
245	        <div className="border-t border-white/[0.06] bg-navy-950/95 backdrop-blur-xl lg:hidden">
246	          <nav className="rail flex max-h-[70vh] flex-col gap-1 overflow-y-auto py-4">
247	            {PRODUCT_GROUPS.map((g) => (
248	              <div key={g.title} className="mb-1">
249	                <p className="section-label px-3 pb-1 pt-2">{g.title}</p>
250	                {g.items.map((it) => (
251	                  <Link key={it.label} href={it.href} className="flex items-center gap-3 rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white">
252	                    <span className="text-brand-300">{it.icon({ size: 18 })}</span>
253	                    {it.label}
254	                    {it.badge && <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-brand-200">{it.badge}</span>}
255	                  </Link>
256	                ))}
257	              </div>
258	            ))}
259	            <div className="my-1 border-t border-white/[0.06]" />
260	            {[{ label: "Pricing", href: "/pricing" }, { label: "Compare", href: "/compare" }, { label: "Blog", href: "/blog" }, ...COMPANY].map((l) => (
261	              <Link key={l.href} href={l.href} className="rounded-lg px-3 py-2.5 text-sm font-medium text-slate-300 hover:bg-white/[0.05] hover:text-white">
262	                {l.label}
263	              </Link>
264	            ))}
265	            <div className="mt-2 flex flex-col gap-2 border-t border-white/[0.06] pt-3">
266	              {authed ? (
267	                <>
268	                  <Link href="/dashboard/settings" className="btn-secondary w-full">My account</Link>
269	                  <Link href="/dashboard" className="btn-primary w-full">Back to portal</Link>
270	                </>
271	              ) : (
272	                <>
273	                  <Link href="/login" className="btn-secondary w-full">Log in</Link>
274	                  <Link href="/register" className="btn-primary w-full">Get started</Link>
275	                </>
276	              )}
277	            </div>
278	          </nav>
279	        </div>
280	      )}
281	    </header>
282	  );
283	}
284	
285	function TopLink({ href, pathname, children }: { href: string; pathname: string; children: React.ReactNode }) {
286	  const active = pathname === href;
287	  return (
288	    <Link href={href} className={`nav-underline rounded-lg px-3 py-2 text-sm font-medium transition-colors ${active ? "is-open text-white" : "text-slate-400 hover:text-white"}`}>
289	      {children}
290	    </Link>
291	  );
292	}
293	
294	function MegaItem({ item }: { item: Item }) {
295	  return (
296	    <Link href={item.href} className="group flex items-start gap-3 rounded-xl px-2 py-2 transition-colors hover:bg-white/[0.05]">
297	      <span className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-white/[0.06] bg-white/[0.03] text-brand-300 transition-colors group-hover:border-brand-500/30 group-hover:text-brand-200">
298	        {item.icon({ size: 17 })}
299	      </span>
300	      <span className="min-w-0">
301	        <span className="flex items-center gap-1.5 text-sm font-medium text-slate-100">
302	          {item.label}
303	          {item.badge && <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-brand-200">{item.badge}</span>}
304	        </span>
305	        <span className="block truncate text-xs text-slate-500">{item.desc}</span>
306	      </span>
307	    </Link>
308	  );
309	}
310	
311	function Chevron({ open }: { open: boolean }) {
312	  return (
313	    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" className={`transition-transform duration-200 ${open ? "rotate-180" : ""}`}>
314	      <path d="m6 9 6 6 6-6" />
315	    </svg>
316	  );
317	}
